- w2: mutex_lock {"resource": "main::m"}; semaphore_release {"resource": "main::g12"}; condvar_wait {"condvar": "main::cv", "lock": "main::m"}; mutex_unlock {"resource": "main::m"}; semaphore_release {"resource": "main::gN"}; return {}
- notifier: semaphore_acquire {"resource": "main::g12"}; semaphore_acquire {"resource": "main::g12"}; mutex_lock {"resource": "main::m"}; condvar_notify_all {"condvar": "main::cv"}; mutex_unlock {"resource": "main::m"}; semaphore_acquire {"resource": "main::gN"}; semaphore_acquire {"resource": "main::gN"}; return {}

